const p = "C:\\Users\\jjq21\\.dsh\\our-free-model\\feed.json";
const r = await tools.read({ file_path: p, limit: 1 });
// feed is single-line JSON; parse via pwsh to pretty print selected parts
const script = `
$j = Get-Content '${p}' -Raw | ConvertFrom-Json
"count: " + $j.announcements.Count
foreach ($a in $j.announcements) {
  "--- $($a.id) [$($a.level)] $($a.title)"
}
`;
const r2 = await tools.pwsh({ command: script, description: "List plugin announcement titles" });
console.log(r2.kind === "foreground" ? r2.stdout.text : JSON.stringify(r2).slice(0,300));

